// ============================================
// DETECT INTENT (RFC-007)
// ============================================

const input = $input.first().json;
const content = (input.data?.content || '').trim().toLowerCase();

const PATTERNS = {
  greeting: /^(bonjour|salut|hello|hey|coucou|bonsoir|yo|hi|bjr|slt)\b/i,
  help: /^(aide|help|commandes?|comment (ça marche|utiliser|faire)|\?\?\?)$/i,
  empty: /^\s*$/
};

let intent = 'question';
let confidence = 0.5;
let skip_llm = false;

if (PATTERNS.empty.test(content)) {
  intent = 'empty';
  confidence = 1.0;
  skip_llm = true;
} else if (PATTERNS.greeting.test(content)) {
  intent = 'greeting';
  confidence = 0.95;
  skip_llm = true;
} else if (PATTERNS.help.test(content)) {
  intent = 'help';
  confidence = 0.95;
  skip_llm = true;
}

return {
  project_id: input.project_id,
  data: input.data,
  llm_config: input.llm_config,
  branding: input.branding,
  detected_intent: intent,
  confidence: confidence,
  skip_llm: skip_llm
};

// ============================================
// PREDEFINED RESPONSES (RFC-007 + RFC-009 v2)
// ============================================

const input = $input.first().json;
const intent = input.detected_intent;
const displayName = input.data?.display_name || 'ami';
const botName = input.branding?.name || 'Assistant';

const RESPONSES = {
  greeting: {
    response: `Bonjour ${displayName} ! Comment puis-je t'aider ?`,
    intent: 'greeting',
    confidence: 1.0,
    tokens_used: 0,
    credits_consumed: 0
  },
  help: {
    response: `Je suis ${botName}. Pose-moi une question et je ferai de mon mieux pour t'aider !`,
    intent: 'help',
    confidence: 1.0,
    tokens_used: 0,
    credits_consumed: 0
  },
  empty: {
    response: `Tu m'as mentionné mais sans message ! Pose-moi une question.`,
    intent: 'empty',
    confidence: 1.0,
    tokens_used: 0,
    credits_consumed: 0
  }
};

const result = RESPONSES[intent] || RESPONSES.empty;

return {
  success: true,
  ...result,
  project_id: input.project_id,
  user_id: input.data?.user_id,
  guild_id: input.data?.guild_id,
  request_content: input.data?.content || ''
};

// ============================================
// BUILD LLM REQUEST (RFC-009 v2)
// ============================================

const input = $input.first().json;
const llmConfig = input.llm_config || {};
const branding = input.branding || {};

// Determine provider (from llm_config or default to gemini)
const provider = llmConfig.provider || 'gemini';

// Build the request for LLM - Web Search
const llmRequest = {
  query: input.data.content,
  provider: provider,
  user_id: input.data.user_id
};

// Add API keys from llm_config
if (llmConfig.openai_api_key) llmRequest.openai_api_key = llmConfig.openai_api_key;
if (llmConfig.anthropic_api_key) llmRequest.anthropic_api_key = llmConfig.anthropic_api_key;
if (llmConfig.google_api_key) llmRequest.google_api_key = llmConfig.google_api_key;
if (llmConfig.mistral_api_key) llmRequest.mistral_api_key = llmConfig.mistral_api_key;

// Add allowed_context for scope classification (RFC-009 v2)
// Use scope_prompt directly as the description for LLM classification
if (branding.scope_prompt) {
  llmRequest.allowed_context = {
    description: branding.scope_prompt,
    suggestion: branding.out_of_scope_message || 'Cette question est hors de mon domaine de compétence.'
  };
}

// Store original data for later use
return {
  llm_request: llmRequest,
  original: {
    project_id: input.project_id,
    data: input.data,
    branding: branding
  }
};

// ============================================
// FORMAT LLM SUCCESS RESPONSE (RFC-009)
// ============================================

const llmResponse = $input.first().json;
const originalData = $('Build LLM Request').first().json.original;

// Extract content from LLM response
const content = llmResponse.data?.content || llmResponse.data?.query?.content || '';
const sources = llmResponse.data?.sources || [];
const usage = llmResponse.usage || {};

const tokensUsed = usage.total_tokens || 0;

// Calculate credits (simple formula)
const creditsConsumed = Math.min(Math.ceil(1 + (tokensUsed / 1000) * 0.5), 10);

// Format response with sources if available
let response = content;
if (sources.length > 0) {
  response += '\n\n**Sources:**';
  sources.slice(0, 3).forEach(s => {
    response += `\n• [${s.title || s.domain}](${s.url})`;
  });
}

return {
  success: true,
  response: response,
  intent: 'question',
  confidence: 0.9,
  tokens_used: tokensUsed,
  credits_consumed: creditsConsumed,
  project_id: originalData.project_id,
  user_id: originalData.data?.user_id,
  guild_id: originalData.data?.guild_id,
  request_content: originalData.data?.content || ''
};

// ============================================
// HANDLE LLM ERROR (RFC-009 v2)
// ============================================

const llmResponse = $input.first().json;
const originalData = $('Build LLM Request').first().json.original;
const branding = originalData.branding || {};

let response = "Je n'ai pas bien compris. Peux-tu reformuler ?";
let intent = 'unknown';

// Check if it's a CONTEXT_VIOLATION (out of scope)
const errorStatus = llmResponse.error?.status || '';
const errorCode = llmResponse.error?.code || 0;

if (errorStatus === 'CONTEXT_VIOLATION' || errorCode === 403) {
  // Out of scope - use out_of_scope_message or suggestion from error
  const suggestion = llmResponse.error?.details?.suggestion || '';
  const outOfScopeMessage = branding.out_of_scope_message || '';

  if (outOfScopeMessage) {
    response = outOfScopeMessage;
  } else if (suggestion) {
    response = suggestion;
  } else {
    response = 'Cette question est hors de mon domaine de compétence.';
  }
  intent = 'out_of_scope';
} else if (errorStatus === 'BAD_REQUEST' || errorCode === 400) {
  // Missing API key or invalid request
  response = "Désolé, je ne peux pas répondre pour le moment. Configuration manquante.";
  intent = 'error';
} else {
  // Generic error
  response = "Désolé, une erreur s'est produite. Réessaie dans quelques instants.";
  intent = 'error';
}

return {
  success: true,
  response: response,
  intent: intent,
  confidence: 0.8,
  tokens_used: 0,
  credits_consumed: 0,
  project_id: originalData.project_id,
  user_id: originalData.data?.user_id,
  guild_id: originalData.data?.guild_id,
  request_content: originalData.data?.content || ''
};
